<?php require_once __DIR__.'/../auth.php'; require_admin(); $uploadDir=__DIR__.'/uploads'; if(!is_dir($uploadDir))mkdir($uploadDir,0755,true); $id=(int)($_GET['id']??$_POST['id']??0);$row=['title'=>'','category'=>'Technology','event_date'=>'','location'=>'','description'=>'','poster'=>null];$errors=[];
if($id){$s=$conn->prepare('SELECT * FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$old=$s->get_result()->fetch_assoc();$s->close();if(!$old){set_flash('Event not found.','error');redirect('index.php');}$row=$old;}
if($_SERVER['REQUEST_METHOD']==='POST'){$row=array_merge($row,['title'=>trim($_POST['title']??''),'category'=>trim($_POST['category']??''),'event_date'=>trim($_POST['event_date']??''),'location'=>trim($_POST['location']??''),'description'=>trim($_POST['description']??'')]);if($row['title']===''||$row['category']===''||$row['location']==='')$errors[]='Title, category and location are required.';$d=DateTime::createFromFormat('Y-m-d',$row['event_date']);if(!$d||$d->format('Y-m-d')!==$row['event_date'])$errors[]='Enter a valid event date.';$newPoster=null;
 if(isset($_FILES['poster'])&&$_FILES['poster']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['poster'];if($f['error']!==UPLOAD_ERR_OK)$errors[]='Poster upload failed.';elseif($f['size']>2*1024*1024)$errors[]='Poster must be 2 MB or smaller.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$errors[]='Only JPEG, PNG, and WebP images are allowed.';else{$newPoster=bin2hex(random_bytes(16)).'.'.$allowed[$mime];}}}
 if(!$errors){if($newPoster&&!move_uploaded_file($_FILES['poster']['tmp_name'],$uploadDir.'/'.$newPoster))$errors[]='Could not store uploaded poster.';else{try{if($id){if($newPoster){$s=$conn->prepare('UPDATE events SET title=?,category=?,event_date=?,location=?,description=?,poster=? WHERE id=?');$s->bind_param('ssssssi',$row['title'],$row['category'],$row['event_date'],$row['location'],$row['description'],$newPoster,$id);}else{$s=$conn->prepare('UPDATE events SET title=?,category=?,event_date=?,location=?,description=? WHERE id=?');$s->bind_param('sssssi',$row['title'],$row['category'],$row['event_date'],$row['location'],$row['description'],$id);}}else{$s=$conn->prepare('INSERT INTO events(title,category,event_date,location,description,poster) VALUES(?,?,?,?,?,?)');$s->bind_param('ssssss',$row['title'],$row['category'],$row['event_date'],$row['location'],$row['description'],$newPoster);}$s->execute();$s->close();if($newPoster&&$row['poster']&&is_file($uploadDir.'/'.$row['poster']))unlink($uploadDir.'/'.$row['poster']);log_action($conn,(int)$_SESSION['student_id'],$id?'event_update':'event_create',$row['title']);set_flash('Event saved successfully.');redirect('index.php');}catch(mysqli_sql_exception $ex){if($newPoster&&is_file($uploadDir.'/'.$newPoster))unlink($uploadDir.'/'.$newPoster);$errors[]='Could not save event.';}}}}
page_start($id?'Edit Event':'Add Event');if($errors){echo '<ul class="flash error">';foreach($errors as $er)echo '<li>'.e($er).'</li>';echo '</ul>';}
?>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><label>Title</label><input name="title" required maxlength="150" value="<?=e($row['title'])?>"><label>Category</label><select name="category"><?php foreach(['Technology','Sports','Cultural','Career','Workshop','Other'] as $c):?><option <?=$row['category']===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><label>Event date</label><input type="date" name="event_date" required value="<?=e($row['event_date'])?>"><label>Location</label><input name="location" required value="<?=e($row['location'])?>"><label>Description</label><textarea name="description" rows="4"><?=e($row['description'])?></textarea><label>Poster (JPEG/PNG/WebP, max 2 MB)</label><input type="file" name="poster" accept="image/jpeg,image/png,image/webp"><?php if($row['poster']):?><p>Current poster: <?=e($row['poster'])?></p><?php endif;?><button>Save event</button></form><?php page_end(); ?>
